Q: Detaching a posix thread vs detaching a std::thread A: <p>I've rewritten your program to use pthreads. It behaves exactly the same.</p>
<pre class="lang-cpp prettyprint-override"><code>#include&lt;pthread.h&gt;
#include&lt;unistd.h&gt;
#include&lt;iostream&gt;
#include&lt;string&gt;

struct Global {
  ~Global(){
      std::cout &lt;&lt; &quot;global variables destroyed...\n&quot; &lt;&lt; std::flush; 
  }
} global;

static void* reader(void*){
      std::string s;           
      std::getline(std::cin,s);
      std::cout &lt;&lt;&quot;Detached thread: you entered: &quot;&lt;&lt; s &lt;&lt; std::endl;
      return nullptr;
}

int main(){
      {
         pthread_t t;
         if (int err = pthread_create(&amp;t, nullptr, reader, nullptr)) {
            std::cerr &lt;&lt; &quot;pthread_create failed: &quot; &lt;&lt; err &lt;&lt; '\n';
            return 1;
         }
         pthread_detach(t);
      }
      auto delay = 3; 
      std::cout &lt;&lt; &quot;Waiting for the thread to start (&quot;
                &lt;&lt;  delay 
                &lt;&lt; &quot;s)...\n&quot;
                &lt;&lt;std::flush; 
      sleep(delay);
      std::cout &lt;&lt; &quot;Done... (Try to press Enter)&quot; &lt;&lt; std::endl;

}
</code></pre>
<pre class="lang-none prettyprint-override"><code>$ build/main 
Waiting for the thread to start (3s)...
Done... (Try to press Enter)
global variables destroyed...
asdf
Detached thread: you entered: asdf
</code></pre>
